import{_ as n,C as r,o as a,c as d,a2 as o,j as t,b as l,w as s,a as h,E as p,a3 as c}from"./chunks/framework.Dg_E471K.js";const b=JSON.parse('{"title":"Deploying the server","description":"","frontmatter":{},"headers":[],"relativePath":"docs/deploying-the-server.md","filePath":"docs/deploying-the-server.md"}'),g={name:"docs/deploying-the-server.md"};function u(y,e,k,m,f,v){const i=r("Mermaid");return a(),d("div",null,[e[2]||(e[2]=o('<h1 id="deploying-the-server" tabindex="-1">Deploying the server <a class="header-anchor" href="#deploying-the-server" aria-label="Permalink to &quot;Deploying the server&quot;">​</a></h1><p>The server runs on one Linux machine as Docker containers behind a shared Caddy for HTTPS (<a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>). Health data must stay in the EU or Switzerland under the GDPR, so pick a host there. This page covers the machine; cutting a release and setting up the Deploy workflow are in <a href="./releasing">Releasing</a>.</p><h2 id="what-runs-on-the-machine" tabindex="-1">What runs on the machine <a class="header-anchor" href="#what-runs-on-the-machine" aria-label="Permalink to &quot;What runs on the machine&quot;">​</a></h2><ul><li><strong>Caddy</strong> is the only container with public ports (80 and 443). It runs in its own Compose project, so stopping the app leaves HTTPS up, and it routes each hostname to its container.</li><li><strong>The API server</strong> (http4k on Jetty) serves <a href="./the-api">the API</a> under <code>/api/v1</code> and <code>/health</code>. It applies its database migrations on start (<a href="./adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres">ADR 0022</a>), and <code>/health</code> answers 503 while Postgres doesn&#39;t.</li><li><strong>Postgres</strong> sits on a private network that only the server reaches.</li><li><strong>The web app</strong> is a static Vue container on its own hostname (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>).</li><li><strong>Grafana Alloy</strong> is optional and ships logs to Grafana Cloud (<a href="#logs">Logs</a>).</li></ul><p>The server must run as <strong>one container</strong>. It keeps the phones waiting for a confirmed email in memory, so a second replica would first need those events shared.</p>',5)),t("details",null,[e[1]||(e[1]=t("summary",null,"Containers, networks and volumes",-1)),(a(),l(c,null,{default:s(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20internet((%22Internet%22))%0A%20%20%20%20subgraph%20edgeproject%5B%22Shared%20Caddy%20Compose%20project%22%5D%0A%20%20%20%20%20%20%20%20caddy%5B%22Caddy%20container%3Cbr%2F%3Epublishes%20ports%2080%20%2F%20443%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20serverproject%5B%22Coach%20Poulpy%20Compose%20project%22%5D%0A%20%20%20%20%20%20%20%20server%5B%22API%20server%20container%3Cbr%2F%3Ehttp4k%20%C2%B7%20port%208080%22%5D%0A%20%20%20%20%20%20%20%20postgres%5B(%22Postgres%20container%3Cbr%2F%3Epostgres%3A5432%22)%5D%0A%20%20%20%20%20%20%20%20alloy%5B%22Grafana%20Alloy%20container%3Cbr%2F%3Eoptional%20log%20shipping%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20webproject%5B%22Web%20app%20Compose%20project%22%5D%0A%20%20%20%20%20%20%20%20web%5B%22Static%20web%20container%3Cbr%2F%3EVue%20%C2%B7%20port%208080%22%5D%0A%20%20%20%20end%0A%20%20%20%20edge%5B%22External%20edge%20network%22%5D%0A%20%20%20%20internal%5B%22Private%20internal%20network%22%5D%0A%20%20%20%20caddyData%5B(%22caddy-data%20volume%3Cbr%2F%3ETLS%20certificates%22)%5D%0A%20%20%20%20caddyConfig%5B(%22caddy-config%20volume%3Cbr%2F%3Eautosaved%20routes%22)%5D%0A%20%20%20%20postgresData%5B(%22postgres-data%20volume%3Cbr%2F%3Edatabase%20files%22)%5D%0A%20%20%20%20alloyData%5B(%22alloy-data%20volume%3Cbr%2F%3Elog%20positions%22)%5D%0A%20%20%20%20loki%5B%22Grafana%20Cloud%20Loki%22%5D%0A%20%20%20%20smtp%5B%22SMTP%20provider%22%5D%0A%0A%20%20%20%20internet%20--%3E%7CHTTP%20%2F%20HTTPS%7C%20caddy%0A%20%20%20%20caddy%20--%3E%7Capi.coach-poulpy.com%20via%20edge%7C%20server%0A%20%20%20%20caddy%20--%3E%7Capp.coach-poulpy.com%20via%20edge%7C%20web%0A%20%20%20%20caddy%20-.%20attaches%20to%20.-%3E%20edge%0A%20%20%20%20caddy%20-.%20persists%20.-%3E%20caddyData%0A%20%20%20%20caddy%20-.%20persists%20.-%3E%20caddyConfig%0A%20%20%20%20server%20-.%20attaches%20to%20.-%3E%20edge%0A%20%20%20%20web%20-.%20attaches%20to%20.-%3E%20edge%0A%20%20%20%20server%20-.%20attaches%20to%20.-%3E%20internal%0A%20%20%20%20postgres%20-.%20attaches%20to%20.-%3E%20internal%0A%20%20%20%20server%20--%3E%7CPostgres%20protocol%7C%20postgres%0A%20%20%20%20alloy%20-.%20attaches%20to%20.-%3E%20internal%0A%20%20%20%20alloy%20-.%20reads%20Docker%20logs%20.-%3E%20server%0A%20%20%20%20alloy%20-.%20reads%20Docker%20logs%20.-%3E%20postgres%0A%20%20%20%20alloy%20-.%20pushes%20logs%20when%20enabled%20.-%3E%20loki%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1}))]),e[3]||(e[3]=o(`<h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux with Python 3, Docker Engine and Docker Compose.</li><li>About 1 GB of free memory. The server is capped at 512 MB, and images are built in CI, not on the machine.</li><li>DNS records for the API hostname (<code>api.coach-poulpy.com</code>) and the web app hostname (<code>app.coach-poulpy.com</code>) pointing at the machine.</li><li>SSH, and ports 80 and 443 open (TCP, plus UDP 443 for HTTP/3).</li><li>If the images on <code>ghcr.io</code> are private, log the machine in once with <code>docker login ghcr.io</code> and a token that can read packages.</li></ul><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>Everything deploys from GitHub with <strong>Actions &gt; Deploy &gt; Run workflow</strong>. You never log in to the machine for it. Setting it up once, and every setting it reads, is in <a href="./releasing#deploy-the-server">Deploy the server</a>.</p><ul><li>Settings live in GitHub. The workflow rewrites <code>~/coach-poulpy/.env</code> on every run, so a change made on the machine is lost.</li><li>The workflow uploads the Compose and Caddy files, then <code>~/caddy/deploy.py</code> starts Caddy if needed, starts the server and Postgres, and adds or replaces only this app&#39;s route in Caddy. Other sites on the same Caddy are left alone.</li><li><strong>What to deploy</strong> <code>website</code> deploys the web app to <code>~/coach-poulpy-web</code> without restarting the server. It needs <code>WEB_DOMAIN</code>.</li><li>Check with <code>curl https://api.coach-poulpy.com/health</code> and <code>curl https://app.coach-poulpy.com/.well-known/assetlinks.json</code>.</li></ul><h3 id="traps" tabindex="-1">Traps <a class="header-anchor" href="#traps" aria-label="Permalink to &quot;Traps&quot;">​</a></h3><ul><li><strong>Never run <code>docker compose down -v</code>.</strong> It deletes the volumes, and with them the database.</li><li><code>POSTGRES_PASSWORD</code> only applies when the Postgres volume is first created. Changing it later needs a password change inside Postgres too.</li><li>An HTTPS error is almost always DNS or a blocked port. Look at <code>cd ~/caddy &amp;&amp; docker compose logs caddy</code>.</li><li>If another Caddy already holds ports 80 and 443, remove that container once before the first deploy.</li></ul><h2 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h2><p>The server sends email over SMTP using <code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_USER</code>, <code>SMTP_PASSWORD</code> and <code>MAIL_FROM</code>. Port 465 uses implicit TLS, any other port STARTTLS. Changing provider is a new deploy, not a code change.</p><p><strong>Set <code>SMTP_HOST</code> before opening sign-up.</strong> Without it, nobody gets a confirmation link, and the admin&#39;s <a href="./admin#status">Status</a> says mail isn&#39;t configured. <code>MAIL_FROM</code> is only the default sender: an admin can save another in <a href="./admin#settings">Settings</a>.</p><p>The links in emails point at <code>WEBSITE_URL</code>, the web app by default. On Android they open in the app, thanks to <code>assetlinks.json</code> built from the signing key. On iPhone they open in the browser until there is an Apple Developer account (<a href="https://github.com/tkint/coach-poulpy/issues/24" target="_blank" rel="noreferrer">#24</a>).</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>On the machine, <code>docker compose logs server</code> only reaches back a short while (3 files of 10 MB). For search and longer retention, the deploy can ship logs to the free tier of <a href="https://grafana.com/products/cloud/" target="_blank" rel="noreferrer">Grafana Cloud</a> (Loki), in an EU region:</p><ol><li>Create a free Grafana Cloud stack in an EU region.</li><li>In the stack&#39;s <strong>Loki</strong> details, copy the push URL (<code>https://logs-prod-XXX.grafana.net/loki/api/v1/push</code>) and the user ID.</li><li>Under <strong>Administration &gt; Access policies</strong>, create a policy with the <code>logs:write</code> scope only and generate a token from it.</li><li>Add <code>LOKI_URL</code>, <code>LOKI_USER</code> (variables) and <code>LOKI_PASSWORD</code> (secret, the token) to the <code>production</code> environment (<a href="./releasing#deploy-the-server">Releasing</a>), then deploy again.</li></ol><p>All three are needed: setting only some stops the deploy. Logs are labelled <code>app</code>, <code>environment</code> and <code>service</code>. In Grafana, <strong>Explore</strong> with <code>{app=&quot;coach-poulpy&quot;, service=&quot;server&quot;}</code> shows the server. Alloy needs about 256 MB more memory. To turn shipping off after enabling it, remove the settings and stop Alloy once with <code>docker compose --profile logs stop alloy</code>.</p><p>Logs leave the machine, so they never hold personal data: no secrets, and emails only masked.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Dump Postgres nightly, and before deploying a release with new migrations, since an older server refuses a migrated database. Keep the dumps off the machine, in the EU or Switzerland:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/coachpoulpy-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dump</span></span></code></pre></div><p>Restore with <code>pg_restore -U coachpoulpy -d coachpoulpy --clean</code>, through <code>docker compose exec -T postgres</code>. Back up <code>.env</code> and the Caddy configuration too. Losing Caddy&#39;s certificate volume only means issuing new certificates.</p>`,20))])}const A=n(g,[["render",u]]);export{b as __pageData,A as default};
